refentry.refsect1:
&reftitle.changelog;





    &Version;
    &Description;





    8.0.0

     min lança um ValueError em caso de falhas;
     anteriormente retornava &false; e emitia um alerta E_WARNING.




    8.0.0

     Como as 
     comparações de número e string foram alteradas,
     min não mais retorna um valor
     diferente por conta da ordem dos argumentos informados.

  &reftitle.examples;



    Exemplos de min


<?php
echo min(2, 3, 1, 6, 7), PHP_EOL;  // 1
echo min(array(2, 4, 5)), PHP_EOL; // 2

// 'hello' é uma string não numérica, então -1 é convertido na string "-1" e os
// valores são comparados como strings: "-1" é menor que "hello"
echo min('hello', -1), PHP_EOL;    // -1

// Quando comparando arrays de vários comprimentos, min retorna o mais curto
$val = min(array(2, 2, 2), array(1, 1, 1, 1)); // array(2, 2, 2)
var_dump($val);

// Vários arrays de mesmo tamanho, a comparação ocorre nos elementos, da esquerda para direita
// so in our example: 2 == 2, but 4 < 5
$val = min(array(2, 4, 8), array(2, 5, 1)); // array(2, 4, 8)
var_dump($val);

// Se for fornecido um array e um valor que não seja array, o array nunca é retornado,
// pois as comparações tratam os arrays como maiores que qualquer outro valor
// Dos valores restantes, 42 é convertido na string "42" ao ser comparado com a
// string não numérica 'string', e "42" é menor que "string"
$val = min('string', array(2, 5, 7), 42);   // 42
var_dump($val);

// Se um argumento é null ou booleano, ele será comparado com outros valores
// usando a regra que FALSE < TRUE e NULL == FALSE,
// independente dos tipos envolvidos
// Nos exemplos abaixo -10 e 10 são tratados como TRUE nas comparações
$val = min(-10, FALSE, 10); // FALSE
var_dump($val);

$val = min(-10, NULL, 10);  // NULL
var_dump($val);

// 0, por outro lado, é tratado como FALSE, então é "menor que" TRUE
$val = min(0, TRUE); // 0
var_dump($val);
?>
